const SERVER_CONFIG = {
  port: 3001,
};

const DATABASE_CONFIG = {
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
};

const SEED_DATA = {
  user: { username: "u1" },
  article: { slug: "a1" },
  commentBodies: ["c1", "c2"],
};

const ERROR_CODES = {
  notFound: "not_found",
  serverError: "server_error",
};

module.exports = {
  SERVER_CONFIG,
  DATABASE_CONFIG,
  SEED_DATA,
  ERROR_CODES,
};

const { findCommentsByArticleSlug } = require("./commentsService");
const { sendNotFound, sendServerError } = require("./httpResponses");

function registerRoutes(app) {
  app.get("/api/articles/:slug/comments", getArticleComments);
}

async function getArticleComments(req, res) {
  try {
    const { slug } = req.params;
    const comments = await findCommentsByArticleSlug(slug);
    if (!comments) {
      return sendNotFound(res);
    }

    res.json({ comments });
  } catch (error) {
    sendServerError(res, error);
  }
}

module.exports = { registerRoutes };

import { COMMENT_LOAD_ERROR } from "./config";

function articleCommentsUrl(slug) {
  return `/api/articles/${encodeURIComponent(slug)}/comments`;
}

async function requestJson(url, failureMessage, options = {}) {
  const res = await fetch(url, options);

  if (!res.ok) {
    throw new Error(`${failureMessage}: ${res.status}`);
  }

  return res.json();
}

export async function getComments(slug, options = {}) {
  const data = await requestJson(
    articleCommentsUrl(slug),
    COMMENT_LOAD_ERROR,
    options,
  );

  return data.comments;
}

